#include "machine.hpp"
#include <stdexcept>
#include <fstream>
#include <iterator>
#include <iostream>
static void require(bool ok,const char* msg){if(!ok)throw std::runtime_error(msg);}
static void command(std::vector<uint8_t>& ram,unsigned at,uint64_t word){for(unsigned i=0;i<8;++i)ram[at+i]=uint8_t(word>>(56-8*i));}
static void opcode(n64::Machine& m,uint32_t word){for(unsigned i=0;i<4;++i)m.sp[4096+i]=uint8_t(word>>(24-8*i));m.sp_interface.pc=0;m.sp_interface.status=0;m.rsp.reset();}
static void put(n64::Machine& m,unsigned reg,uint32_t value){require(m.write(n64::sign32(0xa4100000+reg*4),4,value),"CPU DP write");}
static uint32_t get(n64::Machine& m,unsigned reg){uint64_t v=0;require(m.read(n64::sign32(0xa4100000+reg*4),4,v),"CPU DP read");return uint32_t(v);}
int main(int argc,char** argv){try{
 require(argc==2,"original ROM required");std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t> rom{std::istreambuf_iterator<char>(f),{}};n64::Machine m;require(m.load(rom.data(),rom.size()),"ROM load");auto& d=m.dp_interface;auto tick=[&](){d.tick(m.ram,m.sp,m.dp_interrupt);};
 // All 24-bit START encodings, repeated write suppression, frozen END activation.
 for(unsigned raw=0;raw<16777216;++raw){d.reset();put(m,3,8);put(m,0,0xff000000|raw);put(m,0,0x1238);require(get(m,0)==raw/8*8 && get(m,2)==0 && get(m,3)==0x4aa,"START mask/one-deep latch");put(m,1,raw);require(get(m,2)==raw/8*8 && get(m,3)==0xaa,"frozen END activates empty range");}
 for(unsigned flags=0;flags<8;++flags)for(unsigned field=0;field<3;++field)for(unsigned pair=0;pair<4;++pair){d.reset();d.flags=flags;put(m,3,pair<<(field*2));const unsigned want=pair==1?flags&~(1u<<field):pair==2?flags|(1u<<field):flags;require(d.flags==want,"flag command pairs");}
 for(unsigned mask=0;mask<16;++mask){d.reset();d.clock=11;d.command_busy=12;d.pipe_busy=13;d.tmem_busy=14;put(m,3,mask<<6);require(d.tmem_busy==((mask&1)?0:14) && d.pipe_busy==((mask&2)?0:13) && d.command_busy==((mask&4)?0:12) && d.clock==((mask&8)?0:11),"counter clear masks");}
 d.reset();d.clock=d.pipe_busy=0xffffff;tick();require(!d.clock && !d.pipe_busy,"24-bit nominal counter wrap");
 // Every COP0 bank slot reads the same CPU value; writable slots route to the same module.
 for(unsigned reg=0;reg<8;++reg){d.reset();d.start=16;d.end=32;d.current=24;d.active_end=32;d.flags=2;d.clock=101;d.command_busy=102;d.pipe_busy=103;d.tmem_busy=104;opcode(m,0x40020000|((reg+8)<<11));m.rsp.step(m.sp_interface,d,m.sp,m.ram);require(m.rsp.gpr[2]==get(m,reg),"RSP shared DP read bank");opcode(m,0x40820000|((reg+8)<<11));m.rsp.gpr[2]=0xfffffed8;auto want=d;want.write(reg,0xfffffed8);m.rsp.step(m.sp_interface,d,m.sp,m.ram);require(d.snapshot()==want.snapshot(),"RSP shared DP write bank");}
 // Freeze and flush stall commands; queued START/END waits for the running range boundary.
 d.reset();m.dp_interrupt=false;command(m.ram,0x100,0);command(m.ram,0x200,0x2900000000000000ull);put(m,3,8);put(m,0,0x100);put(m,1,0x108);tick();require(d.current==0x100 && !m.dp_interrupt,"freeze");put(m,3,0x24);tick();require(d.current==0x100,"flush");put(m,0,0x200);put(m,1,0x208);require(d.start_valid && d.end_valid && d.current==0x100,"pending range");put(m,3,0x10);tick();require(d.current==0x108 && !m.dp_interrupt,"range end never implies FullSync");tick();require(d.current==0x208 && get(m,3)==0x80 && m.dp_interrupt,"queued FullSync settles pipeline");
 // Extension after sync restarts the pipeline, and XBUS wraps only DMEM, never IMEM.
 command(m.ram,0x208,0);put(m,1,0x210);tick();require(d.current==0x210 && d.pipeline,"range extension");
 d.reset();m.dp_interrupt=false;m.sp.fill(0xff); // Two aligned commands cross the DMEM end; IMEM remains a guard.
 for(unsigned i=0;i<8;++i){m.sp[4088+i]=0;m.sp[i]=uint8_t(0x2900000000000000ull>>(56-i*8));}
 put(m,3,2);put(m,0,0xff8);put(m,1,0x1008);tick();tick();require(d.current==0x1008 && m.dp_interrupt,"XBUS DMEM wrap");
 // Every 16-bit fill code in both pixel sizes; byte oracle is independent of engine shifts.
 uint64_t fills=0;
 for(unsigned raw=0;raw<65536;++raw)for(unsigned size:{2u,3u})for(unsigned layout=0;layout<2;++layout){d.reset();m.dp_interrupt=false;std::fill(m.ram.begin()+0x6ffff8,m.ram.begin()+0x700048,0x5a);d.color_image=(uint64_t(size)<<51)|(3ull<<32)|0x700000;d.other_mode=3ull<<52;d.scissor=layout?0x0040040000c00cull:0x00000000010010ull;d.fill_color=raw*65536+(65535-raw);command(m.ram,0x100,0x3600c00c00000000ull);put(m,0,0x100);put(m,1,0x108);tick();require(!d.blocked && !m.dp_interrupt && d.current==0x108,"fill command consumed without fake IRQ");for(unsigned i=0;i<80;++i){const int index=int(i)-8;uint8_t want=0x5a;const unsigned bpp=size==2?2:4;if(index>=0 && unsigned(index)<16*bpp){const unsigned pixel=unsigned(index)/bpp,x=pixel%4,y=pixel/4;if(!layout || ((x==1 || x==2) && (y==1 || y==2))){const unsigned code=size==3?(index%4<2?raw:65535-raw):(x%2?65535-raw:raw);want=uint8_t(code/(index%2?1:256));}}require(m.ram[0x6ffff8+i]==want,"fill pixels/scissor/tail/guards");}++fills;}
 // Unsupported command/mode/geometry and RAM bound failures retain CURRENT and never IRQ.
 for(unsigned scenario=0;scenario<6;++scenario){d.reset();m.dp_interrupt=false;d.color_image=(2ull<<51)|(3ull<<32)|0x700000;d.other_mode=3ull<<52;d.scissor=0x10010;d.fill_color=0xffffffff;uint64_t word=0x3600c00c00000000ull;if(scenario==0)word=0x0800000000000000ull;if(scenario==1)d.other_mode=0;if(scenario==2)word|=1;if(scenario==3)d.color_image|=1ull<<53;if(scenario==4)d.color_image=(2ull<<51)|(3ull<<32)|0x7ffff8;if(scenario==5){put(m,0,0x900000);put(m,1,0x900008);}else{command(m.ram,0x100,word);put(m,0,0x100);put(m,1,0x108);}const auto ram=m.ram;const unsigned before=d.current;tick();require(d.blocked && d.current==before && !m.dp_interrupt && m.ram==ram,"bounded failure atomicity");}
 // Actual RDP writes preserve cached CPU data until invalidation.
 m.reset();m.ram[0x700000]=9;uint64_t v=0;require(m.cpu.caches.read(m,n64::sign32(0x80700000),1,v,false,3) && v==9,"cache seed");d.color_image=(3ull<<51)|(3ull<<32)|0x700000;d.other_mode=3ull<<52;d.scissor=0x10010;d.fill_color=0x12345678;command(m.ram,0x100,0x3600c00c00000000ull);put(m,0,0x100);put(m,1,0x108);tick();require(m.ram[0x700000]==0x12 && m.cpu.caches.read(m,n64::sign32(0x80700000),1,v,false,3) && v==9,"RDP does not snoop CPU cache");uint32_t tag=0;require(m.cpu.caches.operation(m,17,n64::sign32(0x80700000),tag) && m.cpu.caches.read(m,n64::sign32(0x80700000),1,v,false,3) && v==0x12,"CPU cache invalidate reveals fill");
 // Existing VI scanout consumes actual RDP fill output, with no synthetic framebuffer.
 auto& vi=m.video_interface;vi.reset();vi.write(0,3);vi.write(1,0x700000);vi.write(2,4);vi.write(9,4);vi.write(10,8);vi.write(12,1024);vi.write(13,1024);std::vector<uint32_t> pixels;int width=0,height=0;vi.render(m.ram,pixels,width,height);require(width==4 && height==4,"RDP/VI dimensions");for(auto pixel:pixels){std::array<uint8_t,4> bytes{};std::memcpy(bytes.data(),&pixel,4);require(bytes==std::array<uint8_t,4>{0x12,0x34,0x56,255},"VI displays actual filled RAM");}
 // FullSync reaches the real CPU interrupt path; MI_INIT acknowledgment clears it.
 m.reset();command(m.ram,0x100,0x2900000000000000ull);put(m,0,0x100);put(m,1,0x108);m.mi_mask=32;m.rsp_phase=1;m.cpu.state.cp0[12]=0x401;require(m.write(n64::sign32(0xa0000400),4,0),"CPU NOP");m.cpu.step();require(m.dp_interrupt && m.cpu.exception_taken && (m.cpu.state.cp0[13]&0x400),"FullSync drives CPU interrupt");require(m.write(n64::sign32(0xa4300000),4,0x800) && !m.interrupt_pending(),"MI acknowledges DP level");
 // Save replay with frozen queued lists, diagnostics and interrupt pending; atomic rejection.
 d.flags=2;put(m,0,0x200);put(m,1,0x208);command(m.ram,0x200,0x0800000000000000ull);m.dp_interrupt=true;m.rsp_phase=2;std::vector<uint8_t> saved,after,replay;require(m.save(saved),"DP save");put(m,3,4);m.clock();m.save(after);require(m.restore(saved),"DP restore");put(m,3,4);m.clock();m.save(replay);require(after==replay && d.blocked,"pending DP exact replay");require(m.restore(after),"blocked state restore");
 for(unsigned field=0;field<19;++field){if(field==13)continue;auto bad=saved;const uint64_t invalid=field<4?1:field==4?8:field==5 || field==6 || field==7 || field==12?2:field<12?0x1000000ull:field<17?0x100000000000000ull:field==17?0x100000000ull:6;const size_t at=bad.size()-688+field*8;for(unsigned n=0;n<8;++n)bad[at+n]=uint8_t(invalid>>(56-n*8));require(m.restore(saved) && !m.restore(bad) && m.save(replay) && replay==saved,"invalid DP state atomic rejection");}
 auto old=saved;old.resize(old.size()-688);old[7]='4';require(m.restore(old) && d.snapshot()==n64::DpInterface{}.snapshot() && m.dp_interrupt,"S014 neutral DP conversion preserves older IRQ");
 std::cout<<"16777216 START encodings, 262144 fill/pixel/guard cases; shared CPU/RSP banks, command flags/counters, queued ranges, XBUS wrapping, bounded diagnostics, cache/VI scanout, CPU IRQ and S015 state replay/rejection passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
